svg.script:
const svg=document.documentElement,nodes=[...svg.querySelectorAll('.node')],edges=[...svg.querySelectorAll('.edge')],detail=svg.querySelector('#detail');
const dt=svg.querySelector('#detail-title'),d1=svg.querySelector('#detail-line1'),d2=svg.querySelector('#detail-line2'),d3=svg.querySelector('#detail-line3');
function clear(){nodes.forEach(n=>n.classList.remove('active','dim'));edges.forEach(e=>e.classList.remove('active','dim'));detail.setAttribute('visibility','hidden')}
function popup(x,y,title,l1,l2,l3){detail.setAttribute('transform',`translate(${Math.min(x,4540)} ${Math.max(105,Math.min(y,7440))})`);dt.textContent=title;d1.textContent=l1;d2.textContent=l2;d3.textContent=l3;detail.setAttribute('visibility','visible')}
nodes.forEach(n=>n.addEventListener('click',ev=>{ev.stopPropagation();clear();const id=n.dataset.node,inc=edges.filter(e=>e.dataset.source===id||e.dataset.target===id),near=new Set([id]);inc.forEach(e=>{e.classList.add('active');near.add(e.dataset.source);near.add(e.dataset.target)});nodes.forEach(x=>{if(!near.has(x.dataset.node))x.classList.add('dim')});edges.forEach(e=>{if(!inc.includes(e))e.classList.add('dim')});n.classList.add('active');const r=n.querySelector('rect');popup(+r.getAttribute('x')+30,+r.getAttribute('y')+70,`${id}  ${n.dataset.name}`,n.dataset.step?`主流程位置 P${String(n.dataset.step).padStart(2,'0')}　证据等级 ${n.dataset.grade}`:`非线性主流程节点　证据等级 ${n.dataset.grade}`,`RVA：${n.dataset.rvas}`,`相邻真实边：${inc.length} 条`) }));
edges.forEach(e=>e.addEventListener('click',ev=>{ev.stopPropagation();clear();e.classList.add('active');nodes.forEach(n=>{if(n.dataset.node!==e.dataset.source&&n.dataset.node!==e.dataset.target)n.classList.add('dim')});edges.forEach(x=>{if(x!==e)x.classList.add('dim')});popup(ev.offsetX+25,ev.offsetY+25,`${e.dataset.edge}  ${e.dataset.source} → ${e.dataset.target}`,e.dataset.name,`条件：${e.dataset.condition||'无额外条件'}`,`证据等级：${e.dataset.grade}`)}));
svg.addEventListener('click',clear);
